def enrich(self, cands, buffer) -> int:
    """Probe under-confirmed promising candidates; append any new signals to the buffer."""
    if self.weights is None:
        return 0
    now = time.time()
    picked, added = 0, 0
    for c in cands:
        if picked >= self.max_per_cycle:
            break
        # NOTE: _families is an INT (brain sets cand._families = eff_families) — a self-patch
        # assumed it was a set and called len() on it, crashing every cycle (2026-07-05).
        if getattr(c, "_families", 1) >= 2:                   # already confirmed -> skip
            continue
        if now - self._probed.get(c.ticker, 0) < self.cooldown:
            continue
        self._probed[c.ticker] = now
        picked += 1
        for sig in (_stocktwits(c.ticker, self.weights.get("stocktwits", 0.35))
                    + _gnews_ticker(c.ticker, self.weights.get("google_news", 0.45))):
            buffer.append(sig)
            added += 1
    return added

def enrich_async(self, cands, buffer, executor):
    """Non-blocking enrich: submit probes to thread pool, append results on completion."""
    if self.weights is None:
        return 0
    now = time.time()
    picked, futures = 0, []
    for c in cands:
        if picked >= self.max_per_cycle:
            break
        if getattr(c, "_families", 1) >= 2:
            continue
        if now - self._probed.get(c.ticker, 0) < self.cooldown:
            continue
        self._probed[c.ticker] = now
        picked += 1
        wt = self.weights.get("stocktwits", 0.35)
        wg = self.weights.get("google_news", 0.45)
        futures.append(executor.submit(_stocktwits, c.ticker, wt))
        futures.append(executor.submit(_gnews_ticker, c.ticker, wg))
    added = 0
    for f in futures:
        try:
            for sig in f.result(timeout=12):
                buffer.append(sig)
                added += 1
        except Exception:
            pass
    return added
